package com.onlineassessment.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiration){if(secret.length()<32)throw new IllegalArgumentException("JWT_SECRET must be at least 32 characters"); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String generate(Long id,String email,String role){Date now=new Date(), exp=new Date(now.getTime()+expiration);return Jwts.builder().subject(email).claim("id",id).claim("role",role).issuedAt(now).expiration(exp).signWith(key).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public boolean valid(String t){try{claims(t);return true;}catch(Exception e){return false;}} }
